			continue
		}
		if c.GroupID != want {
			t.Errorf("%q GroupID = %q, want %q", name, c.GroupID, want)
		}
		if !registered[want] {
			t.Errorf("group %q used by %q is not registered on root (cobra panics at Execute)", want, name)
